import React, { useState } from 'react';
import DigitalClock from './components/DigitalClock';
import './App.css';

function App() {
  const [hour12, setHour12] = useState(false);

  return (
    <div className="app">
      <h1>Digital Clock</h1>
      <DigitalClock hour12={hour12} />
      <label className="format-toggle">
        <input
          type="checkbox"
          checked={hour12}
          onChange={(event) => setHour12(event.target.checked)}
        />
        Show 12-hour format (AM/PM)
      </label>
    </div>
  );
}

export default App;

