import React, { useEffect, useState } from 'react';
import { formatTime } from '../utils/formatTime';

function timeToNow() {
  return new Date();
}

function DigitalClock({ clock = new Date(), hour12 = false }) {
  const [now, setNow] = useState(clock);
  const [format, setFormat] = useState(hour12);

  useEffect(() => {
    const timer = setInterval(() => {
      setNow(timeToNow());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // TODO: keep the clock in sync when the toolbar flips the format
  return (
    <div className="clock">
      <div className="clock-display" data-testid="clock-display">
        {formatTime(now, format)}
      </div>
    </div>
  );
}

export default DigitalClock;

