import { describe, test, expect } from 'vitest';
import { render } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import { formatTime } from '../src/utils/formatTime';
import DigitalClock from '../src/components/DigitalClock';

describe('Digital Clock', () => {
  test('24-hour format zero-pads hours, minutes, and seconds', () => {
    const result = formatTime(new Date(2026, 0, 1, 9, 5, 3), false);
    if (result !== '09:05:03') {
      throw new Error(`Expected "09:05:03" but got "${result}"`);
    }
  });

  test('12-hour format converts afternoon hours with PM', () => {
    const result = formatTime(new Date(2026, 0, 1, 13, 5, 3), true);
    if (result !== '1:05:03 PM') {
      throw new Error(`Expected "1:05:03 PM" but got "${result}"`);
    }
  });

  test('midnight renders as 12:00:00 AM, not 00 or 24', () => {
    const result = formatTime(new Date(2026, 0, 1, 0, 0, 0), true);
    if (result !== '12:00:00 AM') {
      throw new Error(`Expected "12:00:00 AM" but got "${result}"`);
    }
  });

  test('noon renders as 12:00:00 PM, not 0', () => {
    const result = formatTime(new Date(2026, 0, 1, 12, 0, 0), true);
    if (result !== '12:00:00 PM') {
      throw new Error(`Expected "12:00:00 PM" but got "${result}"`);
    }
  });

  test('component renders the initial time on mount', () => {
    const { container } = render(
      <DigitalClock clock={new Date(2026, 0, 1, 9, 5, 3)} hour12={false} />
    );
    const display = container.querySelector('.clock-display');
    if (!display) throw new Error('No .clock-display element found');
    if (display.textContent !== '09:05:03') {
      throw new Error(
        `Expected clock to render "09:05:03" on mount but got "${display.textContent}"`
      );
    }
  });

  test('changing the hour12 prop updates the displayed format', () => {
    const fixed = new Date(2026, 0, 1, 13, 5, 3);
    const { container, rerender } = render(
      <DigitalClock clock={fixed} hour12={false} />
    );
    const display = container.querySelector('.clock-display');
    if (!display) throw new Error('No .clock-display element found');
    rerender(<DigitalClock clock={fixed} hour12={true} />);
    if (display.textContent !== '1:05:03 PM') {
      throw new Error(
        `Expected "1:05:03 PM" after switching to 12-hour but got "${display.textContent}"`
      );
    }
  });
});
